    listVolumes: {
        parameters: {
            query?: {
                /** @description Only the rows of this node, matched exactly against the node names the list reports. A name that is not one of them gives an empty list */
                node?: string;
                /** @description Search: a case-insensitive substring of the name, driver, a label (its name or its value) or the stack or compose project. Applied before the 500-row cap */
                q?: string;
                /** @description used: only volumes a container or a swarm service mounts. unused: only volumes nothing mounts. Applied before the 500-row cap */
                usage?: "all" | "used" | "unused";
            };
            header?: never;
            path: {
                /** @description The environment ID */
                envId: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description OK */
            200: {
                headers: {
                    "Cache-Control"?: string;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["VolumeListBody"];
                };
            };
            /** @description environment_unsupported: the engine answers but TierPlan does not manage it. Carries the state, the engine and the reason. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["EnvironmentProblem"];
                };
            };
            /** @description agent_policy_denied: the environment's agent refused a read by its own policy. The detail names the endpoint. */
            502: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["EnvironmentProblem"];
                };
            };
            /** @description environment_offline: the environment cannot be read. Carries its state (pending, reconnecting, offline, revoked or cluster_changed), the reason code and since. */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["EnvironmentProblem"];
                };
            };
        };
    };
